  public static func add(STATUS: pssSolutionStatus, _ fbb: inout FlatBufferBuilder) { fbb.add(element: STATUS.rawValue, def: 0, at: VT.STATUS) }
  public static func addVectorOf(VARIABLES: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: VARIABLES, at: VT.VARIABLES) }
  public static func addVectorOf(OBJECTIVES: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: OBJECTIVES, at: VT.OBJECTIVES) }
  public static func addVectorOf(CONSTRAINTS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: CONSTRAINTS, at: VT.CONSTRAINTS) }
  public static func add(DOMINANCE_RANK: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: DOMINANCE_RANK, def: 0, at: VT.DOMINANCE_RANK) }
  public static func add(CROWDING_DISTANCE: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: CROWDING_DISTANCE, def: 0.0, at: VT.CROWDING_DISTANCE) }
  public static func add(VERIFY_BY_PROPAGATION_RESIDUAL: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: VERIFY_BY_PROPAGATION_RESIDUAL, def: 0.0, at: VT.VERIFY_BY_PROPAGATION_RESIDUAL) }
  public static func add(PROVENANCE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: PROVENANCE, at: VT.PROVENANCE) }
  public static func endPSSSolution(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); fbb.require(table: end, fields: [4]); return end }
  public static func createPSSSolution(
    _ fbb: inout FlatBufferBuilder,
    SOLUTION_IDOffset SOLUTION_ID: Offset,
    STATUS: pssSolutionStatus = .unspecified,
    VARIABLESVectorOffset VARIABLES: Offset = Offset(),
    OBJECTIVESVectorOffset OBJECTIVES: Offset = Offset(),
    CONSTRAINTSVectorOffset CONSTRAINTS: Offset = Offset(),
    DOMINANCE_RANK: UInt32 = 0,
    CROWDING_DISTANCE: Double = 0.0,
    VERIFY_BY_PROPAGATION_RESIDUAL: Double = 0.0,
    PROVENANCEOffset PROVENANCE: Offset = Offset()
  ) -> Offset {
    let __start = PSSSolution.startPSSSolution(&fbb)
    PSSSolution.add(SOLUTION_ID: SOLUTION_ID, &fbb)
    PSSSolution.add(STATUS: STATUS, &fbb)
    PSSSolution.addVectorOf(VARIABLES: VARIABLES, &fbb)
    PSSSolution.addVectorOf(OBJECTIVES: OBJECTIVES, &fbb)
    PSSSolution.addVectorOf(CONSTRAINTS: CONSTRAINTS, &fbb)
    PSSSolution.add(DOMINANCE_RANK: DOMINANCE_RANK, &fbb)
    PSSSolution.add(CROWDING_DISTANCE: CROWDING_DISTANCE, &fbb)
    PSSSolution.add(VERIFY_BY_PROPAGATION_RESIDUAL: VERIFY_BY_PROPAGATION_RESIDUAL, &fbb)
    PSSSolution.add(PROVENANCE: PROVENANCE, &fbb)
    return PSSSolution.endPSSSolution(&fbb, start: __start)
  }
  public static func sortVectorOfPsssolution(offsets:[Offset], _ fbb: inout FlatBufferBuilder) -> Offset {
    var off = offsets
    off.sort { Table.compare(Table.offset(Int32($1.o), vOffset: 4, fbb: &fbb), Table.offset(Int32($0.o), vOffset: 4, fbb: &fbb), fbb: &fbb) < 0 }
    return fbb.createVector(ofOffsets: off)
  }
  fileprivate static func lookupByKey(vector: Int32, key: String, fbb: ByteBuffer) -> PSSSolution? {
    let key = key.utf8.map { $0 }
    var span = fbb.read(def: Int32.self, position: Int(vector - 4))
    var start: Int32 = 0
    while span != 0 {
      var middle = span / 2
      let tableOffset = Table.indirect(vector + 4 * (start + middle), fbb)
      let comp = Table.compare(Table.offset(Int32(fbb.capacity) - tableOffset, vOffset: 4, fbb: fbb), key, fbb: fbb)
      if comp > 0 {
        span = middle
      } else if comp < 0 {
        middle += 1
        start += middle
        span -= middle
      } else {
        return PSSSolution(fbb, o: tableOffset)
      }
    }
    return nil
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.SOLUTION_ID, fieldName: "SOLUTION_ID", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.STATUS, fieldName: "STATUS", required: false, type: pssSolutionStatus.self)
    try _v.visit(field: VT.VARIABLES, fieldName: "VARIABLES", required: false, type: ForwardOffset<Vector<ForwardOffset<PSSVariableValue>, PSSVariableValue>>.self)
    try _v.visit(field: VT.OBJECTIVES, fieldName: "OBJECTIVES", required: false, type: ForwardOffset<Vector<ForwardOffset<PSSObjectiveValue>, PSSObjectiveValue>>.self)
    try _v.visit(field: VT.CONSTRAINTS, fieldName: "CONSTRAINTS", required: false, type: ForwardOffset<Vector<ForwardOffset<PSSConstraintValue>, PSSConstraintValue>>.self)
    try _v.visit(field: VT.DOMINANCE_RANK, fieldName: "DOMINANCE_RANK", required: false, type: UInt32.self)
    try _v.visit(field: VT.CROWDING_DISTANCE, fieldName: "CROWDING_DISTANCE", required: false, type: Double.self)
    try _v.visit(field: VT.VERIFY_BY_PROPAGATION_RESIDUAL, fieldName: "VERIFY_BY_PROPAGATION_RESIDUAL", required: false, type: Double.self)
    try _v.visit(field: VT.PROVENANCE, fieldName: "PROVENANCE", required: false, type: ForwardOffset<PSSProvenance>.self)
    _v.finish()
  }
}

public struct PSSAttestation: FlatBufferTable, FlatbuffersVectorInitializable, Verifiable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
  public var __buffer: ByteBuffer! { return _accessor.bb }
  private var _accessor: Table

  public static var id: String { "$PSS" }
  public static func finish(_ fbb: inout FlatBufferBuilder, end: Offset, prefix: Bool = false) { fbb.finish(offset: end, fileId: PSSAttestation.id, addPrefix: prefix) }
  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let SIGNING_PUBLIC_KEY: VOffset = 4
    static let SIGNED_AT: VOffset = 6
    static let SIGNATURE: VOffset = 8
    static let CANONICAL_JSON_SIGNATURE: VOffset = 10
  }

  ///  Literal Ed25519 public key, encoded as 64 lowercase hexadecimal characters.
  public var SIGNING_PUBLIC_KEY: String! { let o = _accessor.offset(VT.SIGNING_PUBLIC_KEY); return _accessor.string(at: o) }
  public var SIGNING_PUBLIC_KEYSegmentArray: [UInt8]! { return _accessor.getVector(at: VT.SIGNING_PUBLIC_KEY) }
  public var SIGNED_AT: String? { let o = _accessor.offset(VT.SIGNED_AT); return o == 0 ? nil : _accessor.string(at: o) }
  public var SIGNED_ATSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.SIGNED_AT) }
  ///  Ed25519 signature over the size-prefixed FlatBuffer with both signature
  ///  payloads zeroed while preserving their vectors and offsets.
  public var SIGNATURE: FlatbufferVector<UInt8> { return _accessor.vector(at: VT.SIGNATURE, byteSize: 1) }
  public func withUnsafePointerToSignature<T>(_ body: (UnsafeRawBufferPointer, Int) throws -> T) rethrows -> T? { return try _accessor.withUnsafePointerToSlice(at: VT.SIGNATURE, body: body) }
  ///  Ed25519 signature over canonical JSON in IDL field order and capitalization,
  ///  with both signature fields omitted.
  public var CANONICAL_JSON_SIGNATURE: FlatbufferVector<UInt8> { return _accessor.vector(at: VT.CANONICAL_JSON_SIGNATURE, byteSize: 1) }
  public func withUnsafePointerToCanonicalJsonSignature<T>(_ body: (UnsafeRawBufferPointer, Int) throws -> T) rethrows -> T? { return try _accessor.withUnsafePointerToSlice(at: VT.CANONICAL_JSON_SIGNATURE, body: body) }
  public static func startPSSAttestation(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 4) }
  public static func add(SIGNING_PUBLIC_KEY: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SIGNING_PUBLIC_KEY, at: VT.SIGNING_PUBLIC_KEY) }
  public static func add(SIGNED_AT: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SIGNED_AT, at: VT.SIGNED_AT) }
  public static func addVectorOf(SIGNATURE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SIGNATURE, at: VT.SIGNATURE) }
  public static func addVectorOf(CANONICAL_JSON_SIGNATURE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: CANONICAL_JSON_SIGNATURE, at: VT.CANONICAL_JSON_SIGNATURE) }
  public static func endPSSAttestation(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); fbb.require(table: end, fields: [4, 8, 10]); return end }
  public static func createPSSAttestation(
    _ fbb: inout FlatBufferBuilder,
    SIGNING_PUBLIC_KEYOffset SIGNING_PUBLIC_KEY: Offset,
    SIGNED_ATOffset SIGNED_AT: Offset = Offset(),
    SIGNATUREVectorOffset SIGNATURE: Offset,
    CANONICAL_JSON_SIGNATUREVectorOffset CANONICAL_JSON_SIGNATURE: Offset
  ) -> Offset {
    let __start = PSSAttestation.startPSSAttestation(&fbb)
    PSSAttestation.add(SIGNING_PUBLIC_KEY: SIGNING_PUBLIC_KEY, &fbb)
    PSSAttestation.add(SIGNED_AT: SIGNED_AT, &fbb)
    PSSAttestation.addVectorOf(SIGNATURE: SIGNATURE, &fbb)
    PSSAttestation.addVectorOf(CANONICAL_JSON_SIGNATURE: CANONICAL_JSON_SIGNATURE, &fbb)
    return PSSAttestation.endPSSAttestation(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.SIGNING_PUBLIC_KEY, fieldName: "SIGNING_PUBLIC_KEY", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.SIGNED_AT, fieldName: "SIGNED_AT", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.SIGNATURE, fieldName: "SIGNATURE", required: true, type: ForwardOffset<Vector<UInt8, UInt8>>.self)
    try _v.visit(field: VT.CANONICAL_JSON_SIGNATURE, fieldName: "CANONICAL_JSON_SIGNATURE", required: true, type: ForwardOffset<Vector<UInt8, UInt8>>.self)
    _v.finish()
  }
}

public struct PSS: FlatBufferTable, FlatbuffersVectorInitializable, Verifiable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
